// Claude's review tests for A20: why a panel may be empty. agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { siteStatus } from './siteStatus';

describe('siteStatus', () => {
  it('localhost and 127.0.0.1 over http are always on', () => {
    expect(siteStatus('http://localhost:3000/app', [], true)).toBe('on');
    expect(siteStatus('http://127.0.0.1:5173/', [], true)).toBe('on');
    expect(siteStatus('http://localhost/', [], true)).toBe('on');
  });
  it('another site is off until switched on', () => {
    expect(siteStatus('https://shop.example.com/cart', [], true)).toBe('site-off');
    expect(siteStatus('https://shop.example.com/cart', ['https://shop.example.com'], true)).toBe('on');
    expect(siteStatus('https://shop.example.com/cart', ['https://other.example.com'], true)).toBe('site-off');
  });
  it('https localhost needs switching on too (only http localhost is granted at install)', () => {
    expect(siteStatus('https://localhost:8443/', [], true)).toBe('site-off');
  });
  it('the origin must match exactly, port included', () => {
    expect(siteStatus('http://dev.test:8080/', ['http://dev.test'], true)).toBe('site-off');
    expect(siteStatus('http://dev.test:8080/', ['http://dev.test:8080'], true)).toBe('on');
  });
  it('mocking off wins over on, but not over site-off', () => {
    expect(siteStatus('http://localhost:3000/', [], false)).toBe('mocking-off');
    expect(siteStatus('https://shop.example.com/', ['https://shop.example.com'], false)).toBe('mocking-off');
    expect(siteStatus('https://shop.example.com/', [], false)).toBe('site-off');
  });
  it('pages wemock never runs on, and bad input, are unknown', () => {
    expect(siteStatus('chrome://extensions/', [], true)).toBe('unknown');
    expect(siteStatus('', [], true)).toBe('unknown');
    expect(siteStatus('not a url', [], true)).toBe('unknown');
    expect(siteStatus('file:///C:/a.html', [], true)).toBe('unknown');
  });
});
